DELETE t1 FROM cere_shop_cart t1 joIN(
select a.product_id from cere_shop_cart a join cere_shop_product b on b.product_id = a.product_id and
b.shelve_state = 0
) t2 on t2.product_id = t1.product_id
where t1.buyer_user_id = #{buyerUserId}

